// Product.js
import React from 'react';

const Product = ({ product }) => {
  const { name, price, sizes, color, image } = product.attributes;

  // Use the first image URL if available
  const imageUrl = image?.[0]?.formats?.thumbnail?.url || image?.[0]?.url;

  return (
    <div className="product-card">
      {imageUrl && (
        <img src={`http://localhost:1337${imageUrl}`} alt={name} className="product-image" />
      )}
      <h3 className="product-name">{name}</h3>
      <p className="product-price">${price}</p>
      <div className="product-sizes">
        <strong>Sizes:</strong> {sizes?.map(size => size.name).join(', ')}
      </div>
      <div className="product-colors">
        <strong>Colors:</strong> {color?.map(c => c.name).join(', ')}
      </div>
    </div>
  );
};

export default Product;
